def decode_shift(s: str) -> str:
    """
    Takes a string encoded with `encode_shift` (each lowercase letter shifted forward by 5)
    and returns the original decoded string by shifting each character backward by 5.
    """
    return "".join(
        chr(((ord(ch) - 5 - ord('a')) % 26) + ord('a')) for ch in s
    )
