def compare_one(a, b):
    """
    Returns the larger of two values (int, float, or numeric string) preserving
    the original type of the larger value. Returns None if they are numerically
    equal.

    Numeric strings may use '.' or ',' as the decimal separator.
    """
    def _to_number(value):
        # Convert supported types to a comparable float
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, str):
            # Allow ',' as decimal separator
            cleaned = value.strip().replace(',', '.')
            return float(cleaned)
        raise TypeError("Unsupported type")

    num_a = _to_number(a)
    num_b = _to_number(b)

    if num_a > num_b:
        return a
    if num_b > num_a:
        return b
    return None
